    #[test]
    fn run_preserves_non_generated_context_files() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("agent-environment.yml"),
            "name: test\nbackends:\n  claude-code: {}\n",
        )
        .unwrap();

        // Create CLAUDE.md without the agx marker
        let mut f = std::fs::File::create(dir.path().join("CLAUDE.md")).unwrap();
        writeln!(f, "# My hand-written CLAUDE.md").unwrap();
        drop(f);

        // Create .mcp.json without the agx marker
        let mut f = std::fs::File::create(dir.path().join(".mcp.json")).unwrap();
        writeln!(f, r#"{{ "mcpServers": {{}} }}"#).unwrap();
        drop(f);

        let _guard = super::super::PROCESS_ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let original_dir = std::env::current_dir().unwrap();
        std::env::set_current_dir(dir.path()).unwrap();
        let result = run(CleanArgs {});
        std::env::set_current_dir(&original_dir).unwrap();
        drop(_guard);

        assert!(result.is_ok());
        // These should still exist since they don't have the agx marker
        assert!(dir.path().join("CLAUDE.md").exists());
        assert!(dir.path().join(".mcp.json").exists());
    }

    #[test]
    fn run_without_manifest_uses_cwd() {
        let dir = tempfile::tempdir().unwrap();
        // Create .agx dir without a manifest
        std::fs::create_dir_all(dir.path().join(".agx")).unwrap();
        std::fs::write(dir.path().join(".agx/data"), "cache").unwrap();

        let _guard = super::super::PROCESS_ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let original_dir = std::env::current_dir().unwrap();
        std::env::set_current_dir(dir.path()).unwrap();
        let result = run(CleanArgs {});
        std::env::set_current_dir(&original_dir).unwrap();
        drop(_guard);

        assert!(result.is_ok());
        assert!(!dir.path().join(".agx").exists());
    }

    #[test]
    fn run_removes_all_backend_dirs() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("agent-environment.yml"),
            "name: test\nbackends:\n  claude-code: {}\n",
        )
        .unwrap();

        // Create all possible backend dirs
        for d in BACKEND_DIRS {
            std::fs::create_dir_all(dir.path().join(d)).unwrap();
            std::fs::write(dir.path().join(d).join("file.txt"), "data").unwrap();
        }

        let _guard = super::super::PROCESS_ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let original_dir = std::env::current_dir().unwrap();
        std::env::set_current_dir(dir.path()).unwrap();
        let result = run(CleanArgs {});
        std::env::set_current_dir(&original_dir).unwrap();
        drop(_guard);

        assert!(result.is_ok());
        for d in BACKEND_DIRS {
            assert!(!dir.path().join(d).exists(), "{} should have been removed", d);
        }
    }

    #[test]
    fn clean_backend_dir_with_contents() {
        let dir = tempfile::tempdir().unwrap();

        // Create .claude with nested contents
        std::fs::create_dir_all(dir.path().join(".claude/agents")).unwrap();
        std::fs::create_dir_all(dir.path().join(".claude/skills/my-skill")).unwrap();
        std::fs::write(dir.path().join(".claude/settings.json"), "{}").unwrap();
        std::fs::write(dir.path().join(".claude/agents/helper.md"), "# Helper").unwrap();
        std::fs::write(
            dir.path().join(".claude/skills/my-skill/README.md"),
            "# Skill",
        )
        .unwrap();

        assert!(dir.path().join(".claude").exists());
        std::fs::remove_dir_all(dir.path().join(".claude")).unwrap();
        assert!(!dir.path().join(".claude").exists());
    }
